import{_ as i,c as a,o as t,ae as n}from"./chunks/framework.Bw0Gm4PQ.js";const p=JSON.parse('{"title":"Protecting America’s Bank Account Against Fraud, Waste, and Abuse","description":"","frontmatter":{"title":"Protecting America’s Bank Account Against Fraud, Waste, and Abuse","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/03/protecting-americas-bank-account-against-fraud-waste-and-abuse/","publishDate":"2025-03-25T16:07:40-04:00"},"headers":[],"relativePath":"executive-orders/2025-03-25-protecting-americas-bank-account-against-fraud-waste-and-abuse.md","filePath":"executive-orders/2025-03-25-protecting-americas-bank-account-against-fraud-waste-and-abuse.md"}'),s={name:"executive-orders/2025-03-25-protecting-americas-bank-account-against-fraud-waste-and-abuse.md"};function r(o,e,l,c,u,d){return t(),a("div",null,e[0]||(e[0]=[n('<h1 id="protecting-america-s-bank-account-against-fraud-waste-and-abuse" tabindex="-1">Protecting America’s Bank Account Against Fraud, Waste, and Abuse <a class="header-anchor" href="#protecting-america-s-bank-account-against-fraud-waste-and-abuse" aria-label="Permalink to &quot;Protecting America’s Bank Account Against Fraud, Waste, and Abuse&quot;">​</a></h1><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/03/protecting-americas-bank-account-against-fraud-waste-and-abuse/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/03/protecting-americas-bank-account-against-fraud-waste-and-abuse/</a></p><p>Published: Tuesday, March 25, 2025</p><ul><li><p><strong>Purpose</strong>: Enhance financial integrity, operational efficiency, and accountability within the Federal Government&#39;s financial transactions.</p></li><li><p><strong>Background</strong>:</p><ul><li>The Federal Government disburses and receives trillions annually.</li><li>In FY 2024, $33.9 trillion was deposited into the General Fund; $33.6 trillion was disbursed.</li><li>The Department of the Treasury manages the General Fund but lacks necessary controls to track transactions.</li></ul></li><li><p><strong>Challenges</strong>:</p><ul><li>Financial fraud undermines trust and integrity in federal programs, with estimated losses of $233 - $521 billion annually.</li><li>Agencies&#39; outdated technology and data access problems hinder fraud prevention.</li></ul></li><li><p><strong>Key Provisions</strong>:</p><ul><li>Treasury to conduct fraud screening before disbursements.</li><li>Agencies required to provide detailed financial information to Treasury for tracking.</li><li>Disbursing functions to be centralized under the Treasury where feasible.</li></ul></li><li><p><strong>Specific Actions</strong>:</p><ul><li><p><strong>Pre-Certification Verification</strong>:</p><ul><li>Treasury to enhance systems to mandate verification processes before payments are made.</li><li>Emphasize compliance with the Do Not Pay Working System.</li></ul></li><li><p><strong>Agency Cooperation</strong>:</p><ul><li>Agencies must support Treasury in determining payment eligibility.</li><li>Heads of agencies must review and modify record systems to enable data sharing for fraud prevention.</li></ul></li><li><p><strong>Consolidation of Financial Systems</strong>:</p><ul><li>OMB to direct consolidation of core financial systems within agencies.</li><li>Non-CFO Act agencies to also consolidate under approved providers.</li></ul></li><li><p><strong>Disbursing Authority</strong>:</p><ul><li>Treasury to assess and potentially revoke delegated disbursing authority from agencies.</li><li>Transition of disbursing activities to Treasury’s Chief Disbursing Officer, where feasible.</li></ul></li></ul></li><li><p><strong>Reporting Requirements</strong>:</p><ul><li>Agencies must submit compliance plans detailing their transition strategies.</li><li>Treasury to report progress on implementation within 180 days.</li></ul></li><li><p><strong>Security Measures</strong>: Ensure that classified information and personal data are protected during execution of the order.</p></li><li><p><strong>Legal Considerations</strong>:</p><ul><li>The order does not change existing legal authorities or create enforceable rights against the U.S. government.</li></ul></li></ul>',4)]))}const f=i(s,[["render",r]]);export{p as __pageData,f as default};
